import { defineStyles } from '@/utils'
import { View } from 'react-native'
import { colors } from '@/theme'
import Animated, {
	useAnimatedStyle,
	useSharedValue,
	withSpring,
	withTiming
} from 'react-native-reanimated'
import { useEffect } from 'react'

const DOT_SIZE = 6
const ACTIVE_DOT_SIZE = 10
const SPRING_CONFIG = { dampingRatio: 0.5 }

const Dot = ({ isActive }: { isActive: boolean }) => {
	const width = useSharedValue(isActive ? ACTIVE_DOT_SIZE : DOT_SIZE)
	const opacity = useSharedValue(isActive ? 1 : 0.2)

	useEffect(() => {
		width.value = withSpring(
			isActive ? ACTIVE_DOT_SIZE : DOT_SIZE,
			SPRING_CONFIG
		)
		opacity.value = withTiming(isActive ? 1 : 0.2, { duration: 200 })
	}, [isActive])

	const animatedStyle = useAnimatedStyle(() => ({
		width: width.value,
		opacity: opacity.value
	}))

	return (
		<Animated.View
			style={[styles.dot, animatedStyle, isActive && styles.activeDotBase]}
		/>
	)
}

export const PaginationDots = ({
	currentIndex,
	totalPages
}: {
	currentIndex: number
	totalPages: number
}) => {
	return (
		<View style={styles.container}>
			{Array.from({ length: totalPages }).map((_, index) => (
				<Dot key={index} isActive={currentIndex === index} />
			))}
		</View>
	)
}

const styles = defineStyles({
	container: {
		flexDirection: 'row',
		justifyContent: 'center',
		alignItems: 'center',
		gap: 6
	},
	dot: {
		height: DOT_SIZE,
		borderRadius: 99,
		backgroundColor: `${colors.light.white}33`
	},
	activeDotBase: {
		backgroundColor: colors.light.white
	}
})
